import{_ as e,o as a,c as i,a0 as r}from"./chunks/framework.CShDTZbC.js";const u=JSON.parse('{"title":"Web UI","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/webui.md","filePath":"en/guide/webui.md"}'),o={name:"en/guide/webui.md"};function s(n,t,d,l,h,c){return a(),i("div",null,[...t[0]||(t[0]=[r(`<h1 id="web-ui" tabindex="-1">Web UI <a class="header-anchor" href="#web-ui" aria-label="Permalink to &quot;Web UI&quot;">​</a></h1><p>AirlineSim Autobuy includes a full-featured web management interface built with Vue 3 and Vite. The frontend is embedded in the Go binary, so no separate web server is required.</p><h2 id="accessing-the-web-ui" tabindex="-1">Accessing the Web UI <a class="header-anchor" href="#accessing-the-web-ui" aria-label="Permalink to &quot;Accessing the Web UI&quot;">​</a></h2><p>By default, the web UI is available at <code>http://localhost:9090</code>.</p><p>To change the bind address or port, modify the <code>webui</code> section in your configuration:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">webui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0.0.0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # Bind to all interfaces</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9090</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # HTTP port</span></span></code></pre></div><h3 id="local-only-access" tabindex="-1">Local-Only Access <a class="header-anchor" href="#local-only-access" aria-label="Permalink to &quot;Local-Only Access&quot;">​</a></h3><p>For security, bind to localhost when you do not need remote access:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">webui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">127.0.0.1</span></span></code></pre></div><h2 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h2><p>The dashboard is the main page displayed at <code>http://localhost:9090</code>. It provides a real-time overview of the monitoring engine.</p><h3 id="engine-status" tabindex="-1">Engine Status <a class="header-anchor" href="#engine-status" aria-label="Permalink to &quot;Engine Status&quot;">​</a></h3><p>The top of the dashboard shows the engine status:</p><ul><li><strong>Running</strong> -- Engine is actively scanning markets</li><li><strong>Stopped</strong> -- Engine is idle</li><li><strong>Start/Stop Button</strong> -- Toggle the engine on and off</li></ul><h3 id="server-cards" tabindex="-1">Server Cards <a class="header-anchor" href="#server-cards" aria-label="Permalink to &quot;Server Cards&quot;">​</a></h3><p>Each configured server is displayed as a card showing:</p><table tabindex="0"><thead><tr><th>Metric</th><th>Description</th></tr></thead><tbody><tr><td>Host</td><td>Server label (e.g., <code>free1</code>)</td></tr><tr><td>Scan Count</td><td>Total number of market scans performed</td></tr><tr><td>Found Count</td><td>Number of aircraft that matched rules</td></tr><tr><td>Bought Count</td><td>Number of successful purchases</td></tr><tr><td>Failed Count</td><td>Number of failed purchase attempts</td></tr><tr><td>Last Scan</td><td>Timestamp of the most recent scan</td></tr><tr><td>Last Error</td><td>Most recent error message, if any</td></tr></tbody></table><h3 id="statistics-summary" tabindex="-1">Statistics Summary <a class="header-anchor" href="#statistics-summary" aria-label="Permalink to &quot;Statistics Summary&quot;">​</a></h3><p>Aggregate statistics across all servers:</p><ul><li>Total scans</li><li>Total found aircraft</li><li>Total purchases</li><li>Total failures</li></ul><h3 id="log-feed" tabindex="-1">Log Feed <a class="header-anchor" href="#log-feed" aria-label="Permalink to &quot;Log Feed&quot;">​</a></h3><p>A real-time log feed displays recent events, including:</p><ul><li>Aircraft found matching rules</li><li>Purchase confirmations</li><li>Purchase failures</li><li>Errors and warnings</li><li>Informational messages</li></ul><p>Each log entry includes a timestamp, event type, and message details.</p><h2 id="rules-page" tabindex="-1">Rules Page <a class="header-anchor" href="#rules-page" aria-label="Permalink to &quot;Rules Page&quot;">​</a></h2><p>Navigate to the Rules page to manage purchase rules through the web interface.</p><h3 id="rules-list" tabindex="-1">Rules List <a class="header-anchor" href="#rules-list" aria-label="Permalink to &quot;Rules List&quot;">​</a></h3><p>The rules page displays all configured rules in a table with columns:</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td>#</td><td>Rule index (position in the list)</td></tr><tr><td>Name</td><td>Rule name</td></tr><tr><td>Enabled</td><td>Toggle switch to enable/disable the rule</td></tr><tr><td>Priority</td><td>Rule priority value</td></tr><tr><td>Match</td><td>Summary of match conditions (types, price range, age, etc.)</td></tr><tr><td>Action</td><td>Summary of action settings (auto-buy, snatch, max bid)</td></tr><tr><td>Server</td><td>Which server the rule targets</td></tr><tr><td>Actions</td><td>Edit, toggle, delete buttons</td></tr></tbody></table><h3 id="creating-a-rule" tabindex="-1">Creating a Rule <a class="header-anchor" href="#creating-a-rule" aria-label="Permalink to &quot;Creating a Rule&quot;">​</a></h3><p>Click the <strong>Add Rule</strong> button to open the rule editor. Fill in the following fields:</p><p><strong>Basic Settings:</strong></p><ul><li><strong>Name</strong> -- A descriptive name for the rule</li><li><strong>Enabled</strong> -- Enable the rule immediately</li><li><strong>Priority</strong> -- Priority score (higher = more important)</li><li><strong>Server ID</strong> -- Target server index (or <code>-1</code> for all)</li><li><strong>Auth ID</strong> -- Target auth index (or <code>-1</code> for default)</li></ul><p><strong>Match Conditions:</strong></p><ul><li><strong>Family</strong> -- Select an aircraft family from the dropdown</li><li><strong>Type</strong> -- Select specific aircraft types from the dropdown</li><li><strong>Price Min/Max</strong> -- Price range in AS$</li><li><strong>Max Age</strong> -- Maximum aircraft age in years</li><li><strong>Max Cycles</strong> -- Maximum flight cycles</li><li><strong>Min Condition</strong> -- Minimum condition percentage</li><li><strong>Offer Types</strong> -- Checkboxes for auction and immediate</li><li><strong>Financing</strong> -- Checkboxes for cash, credit, lease</li><li><strong>Sort By</strong> -- Server-side sort order</li></ul><p><strong>Action Settings:</strong></p><ul><li><strong>Auto Buy</strong> -- Enable automatic purchase</li><li><strong>Snatch</strong> -- Enable snatch mode</li><li><strong>Max Bid Increment</strong> -- Maximum bid increment for auctions</li></ul><h3 id="editing-a-rule" tabindex="-1">Editing a Rule <a class="header-anchor" href="#editing-a-rule" aria-label="Permalink to &quot;Editing a Rule&quot;">​</a></h3><p>Click the <strong>Edit</strong> button on any rule to modify its settings. The rule editor is pre-filled with the current values.</p><h3 id="enabling-disabling-a-rule" tabindex="-1">Enabling/Disabling a Rule <a class="header-anchor" href="#enabling-disabling-a-rule" aria-label="Permalink to &quot;Enabling/Disabling a Rule&quot;">​</a></h3><p>Click the <strong>Toggle</strong> button or the enabled switch to quickly enable or disable a rule without opening the editor.</p><h3 id="deleting-a-rule" tabindex="-1">Deleting a Rule <a class="header-anchor" href="#deleting-a-rule" aria-label="Permalink to &quot;Deleting a Rule&quot;">​</a></h3><p>Click the <strong>Delete</strong> button to remove a rule. The deletion is immediate and the configuration file is updated.</p><h3 id="reordering-rules" tabindex="-1">Reordering Rules <a class="header-anchor" href="#reordering-rules" aria-label="Permalink to &quot;Reordering Rules&quot;">​</a></h3><p>Use the drag handle or the <strong>Reorder</strong> feature to change rule priority order. Rules are evaluated in list order.</p><h2 id="settings-page" tabindex="-1">Settings Page <a class="header-anchor" href="#settings-page" aria-label="Permalink to &quot;Settings Page&quot;">​</a></h2><p>The Settings page allows you to view and modify global configuration settings.</p><h3 id="server-settings" tabindex="-1">Server Settings <a class="header-anchor" href="#server-settings" aria-label="Permalink to &quot;Server Settings&quot;">​</a></h3><ul><li>Add, edit, or remove game server entries</li><li>Each server requires a host label and base URL</li></ul><h3 id="authentication-settings" tabindex="-1">Authentication Settings <a class="header-anchor" href="#authentication-settings" aria-label="Permalink to &quot;Authentication Settings&quot;">​</a></h3><ul><li>Add, edit, or remove authentication accounts</li><li>Each account requires username, password, and optional session file path</li></ul><h3 id="monitor-settings" tabindex="-1">Monitor Settings <a class="header-anchor" href="#monitor-settings" aria-label="Permalink to &quot;Monitor Settings&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td>Interval</td><td>Polling interval in seconds</td></tr><tr><td>Jitter</td><td>Random delay in seconds</td></tr><tr><td>Request Timeout</td><td>HTTP request timeout in seconds</td></tr><tr><td>Min Balance</td><td>Minimum account balance to retain (AS$)</td></tr></tbody></table><h3 id="notifier-settings" tabindex="-1">Notifier Settings <a class="header-anchor" href="#notifier-settings" aria-label="Permalink to &quot;Notifier Settings&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td>Console</td><td>Enable/disable console logging</td></tr><tr><td>Discord Webhook</td><td>Discord webhook URL for notifications</td></tr></tbody></table><h3 id="web-ui-settings" tabindex="-1">Web UI Settings <a class="header-anchor" href="#web-ui-settings" aria-label="Permalink to &quot;Web UI Settings&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td>Host</td><td>Bind address for the web UI</td></tr><tr><td>Port</td><td>HTTP port for the web UI</td></tr></tbody></table><h3 id="saving-settings" tabindex="-1">Saving Settings <a class="header-anchor" href="#saving-settings" aria-label="Permalink to &quot;Saving Settings&quot;">​</a></h3><p>Changes to settings are saved to the configuration file immediately. Some changes (like server and auth modifications) require a restart of the application to take effect.</p><h2 id="logs-page" tabindex="-1">Logs Page <a class="header-anchor" href="#logs-page" aria-label="Permalink to &quot;Logs Page&quot;">​</a></h2><p>The Logs page provides a dedicated view of the application log stream.</p><h3 id="log-stream" tabindex="-1">Log Stream <a class="header-anchor" href="#log-stream" aria-label="Permalink to &quot;Log Stream&quot;">​</a></h3><p>Real-time streaming log entries from the running application. Each entry includes:</p><ul><li><strong>Timestamp</strong> -- When the event occurred</li><li><strong>Level</strong> -- INFO, WARN, ERROR</li><li><strong>Message</strong> -- The log message</li><li><strong>Details</strong> -- Additional structured data</li></ul><h3 id="log-levels" tabindex="-1">Log Levels <a class="header-anchor" href="#log-levels" aria-label="Permalink to &quot;Log Levels&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Level</th><th>Color</th><th>Description</th></tr></thead><tbody><tr><td>INFO</td><td>Blue</td><td>Normal operation events</td></tr><tr><td>WARN</td><td>Yellow</td><td>Warnings that do not require immediate action</td></tr><tr><td>ERROR</td><td>Red</td><td>Errors that may require attention</td></tr></tbody></table><h3 id="filtering" tabindex="-1">Filtering <a class="header-anchor" href="#filtering" aria-label="Permalink to &quot;Filtering&quot;">​</a></h3><p>You can filter logs by:</p><ul><li><strong>Level</strong> -- Show only specific log levels</li><li><strong>Search</strong> -- Text search across log messages</li><li><strong>Time range</strong> -- Show logs within a specific time window</li></ul><h2 id="api-endpoints" tabindex="-1">API Endpoints <a class="header-anchor" href="#api-endpoints" aria-label="Permalink to &quot;API Endpoints&quot;">​</a></h2><p>The web UI interacts with the backend through a REST API. These endpoints are also available for external integrations.</p><table tabindex="0"><thead><tr><th>Method</th><th>Endpoint</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/status</code></td><td>Get engine status and statistics</td></tr><tr><td><code>POST</code></td><td><code>/api/control/start</code></td><td>Start the monitoring engine</td></tr><tr><td><code>POST</code></td><td><code>/api/control/stop</code></td><td>Stop the monitoring engine</td></tr><tr><td><code>POST</code></td><td><code>/api/reload</code></td><td>Reload rules without restart</td></tr><tr><td><code>GET</code></td><td><code>/api/config</code></td><td>Get full configuration</td></tr><tr><td><code>PUT</code></td><td><code>/api/config</code></td><td>Update configuration</td></tr><tr><td><code>GET</code></td><td><code>/api/rules</code></td><td>Get all rules</td></tr><tr><td><code>POST</code></td><td><code>/api/rules</code></td><td>Create a new rule</td></tr><tr><td><code>GET</code></td><td><code>/api/rules/{id}</code></td><td>Get a specific rule</td></tr><tr><td><code>PUT</code></td><td><code>/api/rules/{id}</code></td><td>Update a specific rule</td></tr><tr><td><code>DELETE</code></td><td><code>/api/rules/{id}</code></td><td>Delete a rule</td></tr><tr><td><code>PATCH</code></td><td><code>/api/rules/{id}/toggle</code></td><td>Toggle a rule&#39;s enabled state</td></tr><tr><td><code>PUT</code></td><td><code>/api/rules/reorder</code></td><td>Reorder rules</td></tr><tr><td><code>GET</code></td><td><code>/api/aircraft-data</code></td><td>Get aircraft families and types</td></tr></tbody></table><p>For detailed API documentation, see the <a href="/reference/api.html">API Reference</a>.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="/reference/api.html">API Reference</a> for complete endpoint documentation</li><li><a href="/guide/configuration.html">Configuration Guide</a> for web UI configuration options</li><li><a href="/guide/deployment.html">Deployment Guide</a> for reverse proxy setup</li></ul>`,75)])])}const p=e(o,[["render",s]]);export{u as __pageData,p as default};
